def estatisticas(numeros: list[float]) -> tuple[float, float, float]:
    """Retorna maior, menor e média dos números da lista."""
    if not numeros:
        return (0, 0, 0)
    maior = max(numeros)
    menor = min(numeros)
    media = sum(numeros) / len(numeros)
    return (maior, menor, media)
